cd /tmp/vally-eval-trial-r890QV && mkdir -p tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount && cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    // Bronze customer is charged the Bronze price for a basket
    [Fact]
    public void Bronze_customer_is_charged_9500_cents_for_a_10000_cent_basket()
    {
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" 2>&1 | tail -25

